        "Delay Between Messages (seconds)": { ar: "الفاصل بين الرسائل (ثوانٍ)", fa: "فاصله بین پیام‌ها (ثانیه)", ps: "د پیغامونو ترمنځ ځنډ (ثانیې)" },
        "Delay in seconds": { ar: "الفاصل بالثواني", fa: "فاصله به ثانیه", ps: "په ثانیو کې ځنډ" },
