        "delete contact lists and schedules you created;": { ar: "حذف قوائم جهات الاتصال والجدولات التي أنشأتها؛", fa: "حذف فهرست مخاطبین و زمان‌بندی‌هایی که ساخته‌اید؛", ps: "هغه د اړیکو لیستونه او مهالویشونه ړنګول چې تاسو جوړ کړي؛" },
        "Delete selected contacts?": { ar: "حذف جهات الاتصال المحددة؟", fa: "مخاطبین انتخاب‌شده حذف شوند؟", ps: "ټاکل شوې اړیکې ړنګې شي؟" },
        "Delete Session & Rescan QR": { ar: "حذف الجلسة وإعادة مسح QR", fa: "حذف نشست و اسکن دوباره QR", ps: "غونډه ړنګه کړئ او QR بیا سکین کړئ" },
        "Delete this list?": { ar: "حذف هذه القائمة؟", fa: "این فهرست حذف شود؟", ps: "دا لیست ړنګ شي؟" },
