        "Enter creates a new line. Only bold formatting is supported.": { ar: "Enter ينشئ سطراً جديداً. التنسيق العريض فقط مدعوم.", fa: "Enter خط جدید می‌سازد. فقط قالب ضخیم پشتیبانی می‌شود.", ps: "Enter نوې کرښه جوړوي. یوازې غټ لیکل ملاتړ کېږي." },
        "Enter email subject...": { ar: "أدخل موضوع البريد...", fa: "موضوع ایمیل را وارد کنید...", ps: "د بریښنالیک موضوع ولیکئ..." },
        "enter it here": { ar: "أدخله هنا", fa: "اینجا وارد کنید", ps: "دلته یې ولیکئ" },
