        "Import phone lists in": { ar: "استورد قوائم الهاتف من", fa: "فهرست شماره را از اینجا وارد کنید", ps: "د تلیفون لیستونه له دې ځایه وارد کړئ" },
        "Import phone numbers with country code, or paste them.": { ar: "استورد أرقاماً برمز الدولة أو الصقها.", fa: "شماره با کد کشور وارد کنید یا بچسبانید.", ps: "شمېرې له د هېواد کوډ سره وارد کړئ یا یې ونښلوئ." },
        "Insert": { ar: "إدراج", fa: "درج", ps: "ورټولول" },
