        "New signups are currently closed.": { ar: "التسجيلات الجديدة مغلقة حالياً.", fa: "ثبت‌نام جدید فعلاً بسته است.", ps: "نوې نوملیکنې اوس تړلې دي." },
        "No account yet?": { ar: "ليس لديك حساب بعد؟", fa: "هنوز حساب ندارید؟", ps: "لا حساب نه لرئ؟" },
        "No activity in this range.": { ar: "لا نشاط في هذا النطاق.", fa: "در این بازه فعالیتی نیست.", ps: "په دې موده کې فعالیت نشته." },
        "No emails sent yet": { ar: "لم يُرسل بريد بعد", fa: "هنوز ایمیلی ارسال نشده", ps: "لا بریښنالیک نه دی استول شوی" },
        "No files yet. Upload a list to reuse it when you compose.": { ar: "لا ملفات بعد. ارفع قائمة لتعيد استخدامها عند الإنشاء.", fa: "هنوز فایلی نیست. فهرستی آپلود کنید تا هنگام نوشتن دوباره استفاده شود.", ps: "لا دوسیه نشته. یو لیست پورته کړئ چې کله لیکئ یې بیا وکاروئ." },
        "No messages sent yet": { ar: "لم تُرسل رسائل بعد", fa: "هنوز پیامی ارسال نشده", ps: "لا پیغام نه دی استول شوی" },
        "No schedules yet.": { ar: "لا توجد جدولات بعد.", fa: "هنوز زمان‌بندی نیست.", ps: "لا مهالویش نشته." },
        "No sends yet. Activity appears here as soon as Email, WhatsApp, Telegram, or Schedule runs.": { ar: "لا إرسال بعد. يظهر النشاط هنا فور تشغيل البريد أو واتساب أو تيليجرام أو الجدولة.", fa: "هنوز ارسالی نیست. به‌محض اجرای ایمیل، واتساپ، تلگرام یا زمان‌بندی اینجا دیده می‌شود.", ps: "لا استول نشته. کله چې بریښنالیک، واټساپ، ټلیګرام یا مهالویش پیل شي دلته ښکاري." },
        "No verified contacts yet. Upload a list first.": { ar: "لا جهات موثّقة بعد. ارفع قائمة أولاً.", fa: "هنوز مخاطب تأییدشده نیست. ابتدا فهرست آپلود کنید.", ps: "لا تایید شوې اړیکه نشته. لومړی لیست پورته کړئ." },
        "Not a bot token. Leave blank to keep the saved hash.": { ar: "ليس رمز بوت. اتركه فارغاً للإبقاء على القيمة المحفوظة.", fa: "توکن ربات نیست. برای نگه داشتن مقدار ذخیره‌شده خالی بگذارید.", ps: "د بوټ نښه نه ده. د خوندي شوي هش ساتلو لپاره تش پرېږدئ." },
        "Not configured — required for Telegram Connect": { ar: "غير مُعد — مطلوب لاتصال تيليجرام", fa: "پیکربندی نشده — برای اتصال تلگرام لازم است", ps: "نه دی تنظیم شوی — د ټلیګرام نښلولو لپاره اړین" },
        "Numbered List": { ar: "قائمة مرقمة", fa: "فهرست شماره‌دار", ps: "شمېره لیست" },
        "Once": { ar: "مرة واحدة", fa: "یک‌بار", ps: "یو ځل" },
        "Once or daily repeat": { ar: "مرة أو تكرار يومي", fa: "یک‌بار یا تکرار روزانه", ps: "یو ځل یا ورځنی تکرار" },
        "One person or organization should not share a single login in a way that bypasses workspace isolation. You must tell us through Get assistance if you believe your account was used without permission. We may revoke sessions, disable an account, or require a password reset to protect the platform.": { ar: "لا ينبغي لشخص أو منظمة مشاركة تسجيل دخول واحد بما يتجاوز عزل مساحات العمل. يجب أن تخبرنا عبر طلب المساعدة إذا اعتقدت أن حسابك استُخدم دون إذن. قد نلغي الجلسات أو نعطل حساباً أو نطلب إعادة تعيين كلمة المرور لحماية المنصة.", fa: "یک شخص یا سازمان نباید یک ورود را طوری به اشتراک بگذارد که جداسازی فضای کاری دور زده شود. اگر فکر می‌کنید حسابتان بدون اجازه استفاده شده از طریق دریافت راهنمایی به ما بگویید. ممکن است برای محافظت از پلتفرم نشست‌ها را باطل کنیم، حساب را غیرفعال کنیم یا بازنشانی رمز بخواهیم.", ps: "یو کس یا اداره باید یو ننوتل په داسې ډول شریک نه کړي چې د کاري ځای جلاوالی پرېښودل شي. که ګومان کوئ ستاسو حساب پرته له اجازې کارول شوی، د مرسته ترلاسه کړئ له لارې موږ ته ووایاست. موږ کېدای شي غونډې باطلې کړو، حساب نا فعال کړو یا د پلیټفارم ساتنې لپاره د پټنوم بیا تنظیم وغواړو." },
        "Open a tool": { ar: "افتح أداة", fa: "یک ابزار باز کنید", ps: "یوه وسیله پرانیزئ" },
