        "Sign in and open WhatsApp.": { ar: "سجّل الدخول وافتح واتساب.", fa: "وارد شوید و واتساپ را باز کنید.", ps: "ننوزئ او واټساپ پرانیزئ." },
        "Sign in to continue": { ar: "سجّل الدخول للمتابعة", fa: "برای ادامه وارد شوید", ps: "د دوام لپاره ننوزئ" },
